//------------------------------------------------------------------------------
//Callback Name: apply_cb
//功能：执行移动或复制操作
//------------------------------------------------------------------------------
int BlockStyler1::apply_cb()
{
    int errorCode = 0;
    try
    {
        // 1. 获取选中的对象
        std::vector<tag_t> bodyTags;
        if (!GetSelectedBodies(bodyTags))
        {
            BlockStyler1::theUI->NXMessageBox()->Show("以点选择移动和复制",
                NXOpen::NXMessageBox::DialogTypeWarning, "请先选择要操作的对象。");
            return 1;
        }

        // 2. 获取起始点
        PropertyList* ptProps = point0->GetProperties();
        NXOpen::Point3d pickedStart = ptProps->GetPoint3d("Value");
        delete ptProps;
        NXOpen::Point3d effectiveStart = CalculatePointByType(enum0, pickedStart);

        // 3. 获取结束点
        ptProps = point01->GetProperties();
        NXOpen::Point3d pickedEnd = ptProps->GetPoint3d("Value");
        delete ptProps;
        NXOpen::Point3d effectiveEnd = CalculatePointByType(enum01, pickedEnd);

        // 4. 计算平移向量
        double dx = effectiveEnd.X - effectiveStart.X;
        double dy = effectiveEnd.Y - effectiveStart.Y;
        double dz = effectiveEnd.Z - effectiveStart.Z;

        // 如果向量为零，提示
        if (fabs(dx) < 0.0001 && fabs(dy) < 0.0001 && fabs(dz) < 0.0001)
        {
            BlockStyler1::theUI->NXMessageBox()->Show("以点选择移动和复制",
                NXOpen::NXMessageBox::DialogTypeWarning, "起始点和结束点相同，没有位移。");
            return 1;
        }

        // 5. 创建变换矩阵（平移矩阵）
        double matrix[4][4] = {
            {1, 0, 0, dx},
            {0, 1, 0, dy},
            {0, 0, 1, dz},
            {0, 0, 0, 1}
        };

        // 6. 执行操作
        if (moveMode == 0) // 移动
        {
            // 直接对选中的体应用变换
            int nBodies = (int)bodyTags.size();
            std::vector<tag_t> objTags;
            for (int i = 0; i < nBodies; i++)
            {
                objTags.push_back(bodyTags[i]);
            }
            UF_CALL(UF_MODL_transform_objects(objTags.data(), nBodies, matrix));
        }
        else // 复制
        {
            // 先复制体，再移动复制体
            int nBodies = (int)bodyTags.size();
            for (int i = 0; i < nBodies; i++)
            {
                tag_t newBodyTag = NULL_TAG;
                UF_CALL(UF_MODL_copy_body(bodyTags[i], &newBodyTag));
                if (newBodyTag != NULL_TAG)
                {
                    tag_t objToMove[1] = { newBodyTag };
                    UF_CALL(UF_MODL_transform_objects(objToMove, 1, matrix));
                }
            }
        }

        // 刷新图形窗口
        UF_CALL(UF_MODL_update());
    }
    catch(exception& ex)
    {
        //---- Enter your exception handling code here -----
        errorCode = 1;
        BlockStyler1::theUI->NXMessageBox()->Show("Block Styler", NXOpen::NXMessageBox::DialogTypeError, ex.what());
    }
    return errorCode;
}

//------------------------------------------------------------------------------
//Callback Name: update_cb
//功能：响应控件值变化
//------------------------------------------------------------------------------
int BlockStyler1::update_cb(NXOpen::BlockStyler::UIBlock* block)
{
    try
    {
        if(block == button0)
        {
            // 移动按钮被点击
            PropertyList* props = button0->GetProperties();
            bool isSelected = props->GetLogical("Value");
            delete props;
            if (isSelected)
            {
                moveMode = 0; // 切换为移动模式
                PropertyList* props01 = button01->GetProperties();
                props01->SetLogical("Value", false);
                delete props01;
            }
        }
        else if(block == button01)
        {
            // 复制按钮被点击
            PropertyList* props = button01->GetProperties();
            bool isSelected = props->GetLogical("Value");
            delete props;
            if (isSelected)
            {
                moveMode = 1; // 切换为复制模式
                PropertyList* props0 = button0->GetProperties();
                props0->SetLogical("Value", false);
                delete props0;
            }
        }
        else if(block == selection0)
        {
            // 选择对象变更 - 更新显示计数
            UpdateSelectionCount();
        }
        else if(block == point0)
        {
            // 起始点变更 - 存储坐标
            PropertyList* props = point0->GetProperties();
            startPt = props->GetPoint3d("Value");
            delete props;
        }
        else if(block == enum0)
        {
            // 起始点类型变更 - 更新点捕捉方式
            UpdatePointSnapType(enum0, point0);
        }
        else if(block == point01)
        {
            // 结束点变更 - 存储坐标
            PropertyList* props = point01->GetProperties();
            endPt = props->GetPoint3d("Value");
            delete props;
        }
        else if(block == enum01)
        {
            // 结束点类型变更 - 更新点捕捉方式
            UpdatePointSnapType(enum01, point01);
        }
    }
    catch(exception& ex)
    {
        //---- Enter your exception handling code here -----
        BlockStyler1::theUI->NXMessageBox()->Show("Block Styler", NXOpen::NXMessageBox::DialogTypeError, ex.what());
    }
    return 0;
}

//------------------------------------------------------------------------------
//Callback Name: ok_cb
//------------------------------------------------------------------------------
int BlockStyler1::ok_cb()
{
    int errorCode = 0;
    try
    {
        errorCode = apply_cb();
    }
    catch(exception& ex)
    {
        //---- Enter your exception handling code here -----
        errorCode = 1;
        BlockStyler1::theUI->NXMessageBox()->Show("Block Styler", NXOpen::NXMessageBox::DialogTypeError, ex.what());
    }
    return errorCode;
}

