//==============================================================================
// 辅助函数实现
//==============================================================================

//------------------------------------------------------------------------------
// 根据枚举类型计算有效点坐标
// enum0 (起始点类型): 0=边线, 1=体中心, 2=面中心
// enum01 (结束点类型): 0=ABS原点, 1=体中心, 2=面中心, 3=O Y0点, 4=O X0点, 5=O Z0点
//------------------------------------------------------------------------------
NXOpen::Point3d BlockStyler1::CalculatePointByType(
    NXOpen::BlockStyler::Enumeration* enumCtrl, NXOpen::Point3d pickPt)
{
    PropertyList* enumProps = enumCtrl->GetProperties();
    int enumValue = enumProps->GetInteger("Value");
    delete enumProps;

    NXOpen::Point3d result = pickPt;

    // 获取选中的体（用于体中心/面中心计算）
    std::vector<tag_t> bodies;
    GetSelectedBodies(bodies);

    // 判断是哪个枚举控件
    // 通过比较指针判断
    if (enumCtrl == enum0)
    {
        // 起始点类型
        switch (enumValue)
        {
            case 0: // 边线 - 使用拾取点本身
                break;
            case 1: // 体中心
                if (!bodies.empty())
                {
                    double massCenter[3];
                    UF_CALL(UF_MODL_ask_mass_props_3d(bodies[0], 1, 0.0, 0.0, 0.0,
                        massCenter, NULL, NULL, NULL, NULL, NULL, NULL));
                    result = NXOpen::Point3d(massCenter[0], massCenter[1], massCenter[2]);
                }
                break;
            case 2: // 面中心 - 使用拾取点，point0 的捕捉已处理
                break;
        }
    }
    else if (enumCtrl == enum01)
    {
        // 结束点类型
        switch (enumValue)
        {
            case 0: // ABS原点
                result = NXOpen::Point3d(0, 0, 0);
                break;
            case 1: // 体中心
                if (!bodies.empty())
                {
                    double massCenter[3];
                    UF_CALL(UF_MODL_ask_mass_props_3d(bodies[0], 1, 0.0, 0.0, 0.0,
                        massCenter, NULL, NULL, NULL, NULL, NULL, NULL));
                    result = NXOpen::Point3d(massCenter[0], massCenter[1], massCenter[2]);
                }
                break;
            case 2: // 面中心 - 使用拾取点
                break;
            case 3: // O Y0点 - 投影到Y=0平面
                result = NXOpen::Point3d(pickPt.X, 0, pickPt.Z);
                break;
            case 4: // O X0点 - 投影到X=0平面
                result = NXOpen::Point3d(0, pickPt.Y, pickPt.Z);
                break;
            case 5: // O Z0点 - 投影到Z=0平面
                result = NXOpen::Point3d(pickPt.X, pickPt.Y, 0);
                break;
        }
    }

    return result;
}

//------------------------------------------------------------------------------
// 获取选择对象中所有 Body 的 tag
//------------------------------------------------------------------------------
bool BlockStyler1::GetSelectedBodies(std::vector<tag_t>& bodies)
{
    bodies.clear();

    PropertyList* selProps = selection0->GetProperties();
    std::vector<NXOpen::TaggedObject*> selectedObjects = selProps->GetTaggedObjectVector("SelectedObjects");
    delete selProps;

    if (selectedObjects.empty())
        return false;

    // 遍历选中的对象，提取 Body
    for (size_t i = 0; i < selectedObjects.size(); i++)
    {
        NXOpen::Body* body = dynamic_cast<NXOpen::Body*>(selectedObjects[i]);
        if (body != NULL)
        {
            bodies.push_back(body->Tag());
        }
    }

    return !bodies.empty();
}

//------------------------------------------------------------------------------
// 更新选择对象计数显示
//------------------------------------------------------------------------------
void BlockStyler1::UpdateSelectionCount()
{
    PropertyList* selProps = selection0->GetProperties();
    std::vector<NXOpen::TaggedObject*> selectedObjects = selProps->GetTaggedObjectVector("SelectedObjects");
    delete selProps;

    // 构造显示字符串
    char countStr[64];
    sprintf(countStr, "选择对象 (%d)", (int)selectedObjects.size());
    PropertyList* labelProps = selection0->GetProperties();
    labelProps->SetString("Label", countStr);
    delete labelProps;
}

//------------------------------------------------------------------------------
// 更新点拾取控件的捕捉类型
//------------------------------------------------------------------------------
void BlockStyler1::UpdatePointSnapType(
    NXOpen::BlockStyler::Enumeration* enumCtrl,
    NXOpen::BlockStyler::SpecifyPoint* pointCtrl)
{
    PropertyList* enumProps = enumCtrl->GetProperties();
    int enumValue = enumProps->GetInteger("Value");
    delete enumProps;

    PropertyList* pointProps = pointCtrl->GetProperties();

    // 先清除所有捕捉类型
    int clearValue = 0;
    pointProps->SetInteger("SnapPointTypesEnabled", clearValue);

    // 根据枚举类型设置不同的捕捉方式
    if (enumCtrl == enum0)
    {
        switch (enumValue)
        {
            case 0: // 边线 - 启用端点和中点捕捉
            {
                int snapFlags = SnapPointTypesEnabled_EndPoint |
                                SnapPointTypesEnabled_MidPoint |
                                SnapPointTypesEnabled_ControlPoint |
                                SnapPointTypesEnabled_Intersection;
                pointProps->SetInteger("SnapPointTypesEnabled", snapFlags);
                break;
            }
            case 1: // 体中心 - 启用点构造器
            {
                int snapFlags = SnapPointTypesEnabled_PointConstructor |
                                SnapPointTypesEnabled_ArcCenter;
                pointProps->SetInteger("SnapPointTypesEnabled", snapFlags);
                break;
            }
            case 2: // 面中心 - 启用点构造器和端点
            {
                int snapFlags = SnapPointTypesEnabled_PointConstructor |
                                SnapPointTypesEnabled_PointonSurface |
                                SnapPointTypesEnabled_EndPoint;
                pointProps->SetInteger("SnapPointTypesEnabled", snapFlags);
                break;
            }
        }
    }
    else if (enumCtrl == enum01)
    {
        switch (enumValue)
        {
            case 0: // ABS原点 - 不需要捕捉
            {
                int snapFlags = 0;
                pointProps->SetInteger("SnapPointTypesEnabled", snapFlags);
                break;
            }
            case 1: // 体中心
            {
                int snapFlags = SnapPointTypesEnabled_PointConstructor |
                                SnapPointTypesEnabled_ArcCenter;
                pointProps->SetInteger("SnapPointTypesEnabled", snapFlags);
                break;
            }
            case 2: // 面中心
            {
                int snapFlags = SnapPointTypesEnabled_PointConstructor |
                                SnapPointTypesEnabled_PointonSurface |
                                SnapPointTypesEnabled_EndPoint;
                pointProps->SetInteger("SnapPointTypesEnabled", snapFlags);
                break;
            }
            case 3: // O Y0点 - 允许任意点拾取
            case 4: // O X0点
            case 5: // O Z0点
            {
                int snapFlags = SnapPointTypesEnabled_Inferred;
                pointProps->SetInteger("SnapPointTypesEnabled", snapFlags);
                break;
            }
        }
    }

    delete pointProps;
}